import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { normalizeFixture } from "../tooling/fixture-oracle/src/normalize.mjs";

const root = process.cwd();
const manifestPath = path.join(root, "contracts/fixtures/manifest.json");
const manifest = JSON.parse(await readFile(manifestPath, "utf8"));
const suppliedJavaOutput = process.argv[2] === "--java-output" ? process.argv[3] : null;
const expectedDomains = ["agent-loop", "compaction", "protocol", "provider", "session"];
const actualDomains = manifest.fixtures.map((fixture) => fixture.domain).sort();
if (JSON.stringify(actualDomains) !== JSON.stringify(expectedDomains)) {
  throw new Error(`fixture domains differ: ${actualDomains.join(", ")}`);
}
if (manifest.schemaVersion !== "2.0" || manifest.sourceRevision !== "6c87d9a026677b601e8278030dcf1ad97fe0bd86") {
  throw new Error("fixture manifest does not identify the approved Pi revision");
}
await requireHash(path.join(root, manifest.generation.oracle.path), manifest.generation.oracle.sha256, "Pi extraction oracle");
const submoduleRevision = run("git", ["-C", path.join(root, "original-pi"), "rev-parse", "HEAD"]);
if (submoduleRevision !== manifest.sourceRevision) throw new Error("original-pi submodule revision differs from fixture manifest");

for (const fixture of manifest.fixtures) {
  const fixturePath = path.join(root, "contracts/fixtures", fixture.path);
  const expectedPath = path.join(root, "contracts/fixtures", fixture.expectedPath);
  await requireHash(fixturePath, fixture.rawSha256, `${fixture.domain} raw fixture`);
  await requireHash(expectedPath, fixture.expectedSha256, `${fixture.domain} expected projection`);
  for (const source of [...fixture.sourceFiles, ...fixture.testFiles]) {
    await requireHash(path.join(root, "original-pi", source.path), source.sha256, `Pi source ${source.path}`);
  }
  const oracle = await normalizeFixture(fixturePath);
  const expected = JSON.parse(await readFile(expectedPath, "utf8"));
  if (JSON.stringify(oracle) !== JSON.stringify(expected)) {
    throw new Error(`${fixture.domain} TypeScript projection differs from checked-in expected output`);
  }
}

const temp = await mkdtemp(path.join(tmpdir(), "ji-fixture-"));
try {
  const javaOutputPath = suppliedJavaOutput ?? path.join(temp, "java-projections.json");
  if (suppliedJavaOutput === null) runGradleFixtures(javaOutputPath);
  const javaOutputs = JSON.parse(await readFile(javaOutputPath, "utf8"));
  for (const fixture of manifest.fixtures) {
    if (javaOutputs[fixture.domain] === undefined) throw new Error(`missing Java output for ${fixture.domain}`);
    const expected = JSON.parse(await readFile(path.join(root, "contracts/fixtures", fixture.expectedPath), "utf8"));
    if (JSON.stringify(javaOutputs[fixture.domain]) !== JSON.stringify(expected)) {
      throw new Error(`${fixture.domain} Java projection differs from Pi oracle`);
    }
  }
  process.stdout.write(`five Pi fixture domains matched across TypeScript oracle and Java runner\n`);
} finally {
  await rm(temp, { recursive: true, force: true });
}

function runGradleFixtures(outputPath) {
  const wrapper = path.join(root, process.platform === "win32" ? "gradlew.bat" : "gradlew");
  const args = [":ji-test-kit:runFixtures", `-PfixtureSuiteOutput=${outputPath}`, "--offline"];
  if (process.platform === "win32") execFileSync("cmd.exe", ["/d", "/s", "/c", wrapper, ...args], { cwd: root, stdio: "inherit" });
  else execFileSync(wrapper, args, { cwd: root, stdio: "inherit" });
}

async function requireHash(file, expected, label) {
  const actual = createHash("sha256").update(await readFile(file)).digest("hex");
  if (actual !== expected) throw new Error(`${label} hash mismatch: expected ${expected}, got ${actual}`);
}

function run(executable, args) {
  return execFileSync(executable, args, { cwd: root, encoding: "utf8" }).trim();
}

